package com.allegaeon.catworld.controller;
import com.allegaeon.catworld.dto.*; import com.allegaeon.catworld.service.TransferRateService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import static org.springframework.http.HttpStatus.NO_CONTENT;
@RestController @RequiredArgsConstructor @RequestMapping("/api/transfer-rate") public class TransferRateController { private final TransferRateService service; @GetMapping public ResponseEntity<TransferRateResponseDTO> get(){return ResponseEntity.ok(service.get());} @PutMapping public ResponseEntity<TransferRateResponseDTO> configure(@Valid @RequestBody TransferRateRequestDTO request){return ResponseEntity.ok(service.configure(request.getTransferRate()));} @DeleteMapping @ResponseStatus(NO_CONTENT) public void clear(){service.clear();} }
